    request_data = {
        "name": scenario_case["name"],
        "photoUrls": scenario_case["photoUrls"]
    }
    
    # Add optional fields if present in the scenario
    if "category" in scenario_case:
        request_data["category"] = scenario_case["category"]
    if "tags" in scenario_case:
        request_data["tags"] = scenario_case["tags"]
